const input = $input.first().json.body || $input.first().json;
const requestId = input.request_id || `val-${Date.now()}`;
const workDir = `/tmp/cortex-val/${requestId}`;

return [{
  json: {
    repo_url: input.repo_url,
    branch: input.branch || 'main',
    fix_mode: input.fix_mode || 'report',
    request_id: requestId,
    work_dir: workDir,
    base_dir: workDir
  }
}];

const prev = $('Parse Input').first().json;
const cloneOut = $input.first().json.stdout || '';
const success = cloneOut.includes('CLONE_SUCCESS');

return [{
  json: {
    ...prev,
    work_dir: prev.work_dir + '/repo',
    clone_success: success,
    clone_output: cloneOut.substring(0, 500)
  }
}];

const prev = $('Setup').first().json;
const files = ($input.first().json.stdout || '').split('\n').filter(f => f.trim());

const hasPython = files.some(f => f.endsWith('.py'));
const hasJS = files.some(f => f.endsWith('.js') || f.endsWith('.ts'));

return [{
  json: {
    ...prev,
    has_python: hasPython,
    has_javascript: hasJS,
    files_found: files.length,
    sample_files: files.slice(0, 10)
  }
}];

const prev = $('Analyze').first().json;
const ruffOut = $input.first().json.stdout || '[]';

let lintIssues = [];
try {
  lintIssues = JSON.parse(ruffOut);
} catch (e) {
  // ruff may output non-JSON on success
  lintIssues = [];
}

return [{
  json: {
    ...prev,
    lint_issues: lintIssues.slice(0, 50),
    lint_count: lintIssues.length
  }
}];

const prev = $('Parse Lint').first().json;
const trivyOut = $input.first().json.stdout || '{}';

let security = { vulnerabilities: [], secrets: [] };
try {
  const parsed = JSON.parse(trivyOut);
  const results = parsed.Results || [];
  results.forEach(r => {
    if (r.Vulnerabilities) {
      security.vulnerabilities.push(...r.Vulnerabilities.slice(0, 20));
    }
    if (r.Secrets) {
      security.secrets.push(...r.Secrets.slice(0, 10));
    }
  });
} catch (e) {
  security.parse_error = e.message;
}

return [{
  json: {
    ...prev,
    security: security,
    vuln_count: security.vulnerabilities.length,
    secret_count: security.secrets.length
  }
}];

const prev = $('Parse Security').first().json;

const passed = prev.lint_count === 0 && prev.vuln_count === 0 && prev.secret_count === 0;

return [{
  json: {
    success: true,
    passed: passed,
    request_id: prev.request_id,
    repo: prev.repo_url,
    branch: prev.branch,
    summary: {
      files_scanned: prev.files_found,
      lint_issues: prev.lint_count,
      vulnerabilities: prev.vuln_count,
      secrets_found: prev.secret_count
    },
    details: {
      lint: prev.lint_issues,
      security: prev.security
    },
    message: passed ? 'All checks passed' : 'Issues found - review required',
    timestamp: new Date().toISOString()
  }
}];
